import{_ as a,o as l,c as e,a6 as d}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"七步研究清单：从0到1分析一家公司","description":"","frontmatter":{"title":"七步研究清单：从0到1分析一家公司"},"headers":[],"relativePath":"astock-course/14-stock-checklist.md","filePath":"astock-course/docs/14-stock-checklist.md"}'),i={name:"astock-course/14-stock-checklist.md"};function r(o,t,h,p,s,n){return l(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="七步研究清单-从0到1分析一家公司" tabindex="-1">七步研究清单：从0到1分析一家公司 <a class="header-anchor" href="#七步研究清单-从0到1分析一家公司" aria-label="Permalink to &quot;七步研究清单：从0到1分析一家公司&quot;">​</a></h1><p>随便找一家上市公司，打开它的行情页。跳出来的第一样东西多半不是这家公司，是分时图——开盘以来每一分钟成交价连成的那条线。盯着它看十分钟，你能讲出一堆「强弱感受」；再点开资料标签（电脑行情软件里它有个老名字，叫 F10），公司概况、股东研究、财务分析、历年公告一层层展开，往下翻很久都翻不到头——一家像样的上市公司，公开资料摞起来远不止几千页。</p><p>大多数人的「研究」就从那条分时图开始：看看今天涨没涨，听听群里说什么，感觉一下强弱，然后下单。材料从第一步就摆反了——分时图里只有今天的情绪，没有公司；公司的钱从哪来、优势能撑几年、利润是不是真的，全在 F10 那几千页里，一页没翻。很多亏损不是从下单那一刻开始的，是从研究的第一步就选错了原料。</p><p>本章把研究重排成一条带出口的流程。新增的名字只有两个：商业模式——这家公司靠什么赚钱的方式；研究清单——把分析流程写成「每步带通过标准与不通过出口」的检查序列。其余十三块积木全是旧的，本章只做三件新事：给积木排序、给每步配出口、给全程配台账。演练节给出一份以贵州茅台（代码 600519）为例的七步走查记录：材料全部来自免登录的公开信息，只主张长期公开特征并标「约」。一切易变数字（当下的股价与估值）不写具体值，改为留给你的自查动作；示例仅演示流程与记录格式，不构成任何投资建议、不荐股。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章调用十三块旧积木，按七步的次序过一遍接口。看生意的三块：能力圈——三问自查（钱从哪来？谁跟它抢？亏了能说清为什么吗？），答不上就是圈外（第 8 章）；护城河——问「十年后它还在吗」，用优势的持续期给投资设期限（第 8 章）；毛利率——毛利 ÷ 营收，衡量生意好不好做，看趋势也看同行（第 6 章）。看钱的三块：经营现金流——利润的「现金版」，经营现金流 ÷ 净利润长期小于 1 要警惕（第 6 章）；货币资金——账上随时可动用的钱，与有息负债对照着看（第 6 章）；应收账款——货发了钱没收的纸面收入，增速远超营收是红旗（第 6 章）。</p><p>看价格的三块：市盈率——股价 ÷ 每股盈利，静态当回本年限读（第 7 章）；股息率——每年每股分红 ÷ 股价，现金回报的下限标尺（第 7 章）；安全边际——先估内在价值区间，价格打到七折以下才出手（第 8 章）。看行情的两块：趋势——高点低点同时抬升是升势、同时下移是跌势，只描述不预测（第 5 章）；均线——最近 N 日收盘价的平均连成的线，描述方向，不预测拐点（第 5 章）。管自己的两块：仓位管理——单笔可亏额＝总资金 × 单笔风险预算，用（买入价 − 止损价）反推可买数量（第 11 章）；处置效应——盈利急着卖、亏损不肯卖，去留只按基本面判定、留痕对抗（第 12 章）。十三块全部就位，本章不新增第四类积木，只排调用顺序。</p><h2 id="原理-研究输在顺序-不输在勤奋" tabindex="-1">原理：研究输在顺序，不输在勤奋 <a class="header-anchor" href="#原理-研究输在顺序-不输在勤奋" aria-label="Permalink to &quot;原理：研究输在顺序，不输在勤奋&quot;">​</a></h2><h3 id="分时图里没有公司" tabindex="-1">分时图里没有公司 <a class="header-anchor" href="#分时图里没有公司" aria-label="Permalink to &quot;分时图里没有公司&quot;">​</a></h3><p>分时图不是假工具，先把它的真实用途说清：它记录今天每一分钟的成交价与均价，适合看今天的成交节奏、看挂单之后价格的相对位置——都是「当下」的事。把它当研究起点错在哪，一个遮字试验就能看清：遮住分时图角落的代码与名称，你无法从曲线认出这是银行、酒厂还是软件公司。曲线不携带行业、生意与报表的任何信息，它携带的只是这一天的供需情绪。可你买的从来不是那条线，是公司的一份股权（第 2 章）——用不带公司信息的原料去决定买不买这家公司，原料与问题从一开始就不在一张桌子上。</p><p>「研究就是看研报、听消息」这个习惯，先替它说句公道话：研报有专业的加工，消息偶尔也含真信息，二手材料不是不能用。它失效的边界在「替」字上：二手材料替你做完了读这一步，还顺手替你做了判这一步——研报的结论带着发布方的立场（卖方研报的行业惯例，此处取定性口径），消息的来源更不会为你兜底。清单的回答不是拒绝二手材料，是规定位次：一手披露（F10、年报、交易所公告）是证据，二手加工最多是线索，每条线索都要回到披露里对账——对不上账的线索，不进台账。</p><h3 id="商业模式-一句话说清钱从哪来" tabindex="-1">商业模式：一句话说清钱从哪来 <a class="header-anchor" href="#商业模式-一句话说清钱从哪来" aria-label="Permalink to &quot;商业模式：一句话说清钱从哪来&quot;">​</a></h3><p>这个词存在的理由，先用反事实立起来：假如利润表能单独回答「这家公司好不好」，商业模式就是个多余的词。麻烦恰恰在于，同样的利润可以长在完全不同的生意上。载体是三个填空：卖给谁、收什么钱、成本大头是什么——拼成一句话，讲到完全外行的人能复述为止。</p><p>用一道对比演算看清「同样的利润、不同的风险」。甲乙两家虚构公司，营收都是 5 亿，净利润都是 1 亿，利润表并排一模一样。甲先收钱后发货：客户下单先打款，应收账款常年近乎为零，账上反而常年压着客户预付的 1 亿——那是它欠客户的货，不是别人欠它的钱（报表记作预收款项（现行收入准则下多列作「合同负债」，名字变了机制没变），负债一侧）。乙先发货后收钱，客户平均 73 天才付款：应收账款 ≈ 5 亿 × 73 ÷ 365 ＝ 1 亿——它有一年利润量级的钱，常年押在客户手里（应收账款，第 6 章）。两张资产负债表铺开，方向完全相反：甲的 1 亿是客户押给它的定金，乙的 1 亿是它押给客户的信任。资金链一紧——下游拖款、压价、赖账——乙先倒。这也是体检里应收红旗的因果来源（第 6 章）：应收增速远超营收，多半是为了维持营收数字在给客户垫资。</p><p>日常里这套判别随处可用：先款后货的白酒厂、先收租后服务的商场，收的是现钱或准现钱；先垫料生产、验收后再回款还要扣一年质保金的设备厂，垫的是自己的家底。演练选的示例公司恰好是「先收钱」的典型，第③步的体检形态因此天生干净——生意形态与体检结论是同一件事的两面。</p><h3 id="研究清单-每步带出口的检查序列" tabindex="-1">研究清单：每步带出口的检查序列 <a class="header-anchor" href="#研究清单-每步带出口的检查序列" aria-label="Permalink to &quot;研究清单：每步带出口的检查序列&quot;">​</a></h3><p>研究失败的常见形态不是不知道，是临场漏了：行情跳动、群消息闪动，十几项检查靠临场记忆，漏一项是常态。清单的成因就是把「想全」从决策时刻挪到进场之前——事前一页纸，事后不救火。公开世界里这个做法的先例在驾驶舱：飞行员起飞前按检查单逐项核对、逐项应答，不是因为飞行员记性差，是因为关键流程不许依赖记性（公开常识，定性口径）。机械防御管持有期间的纪律（第 12 章），研究清单管进场之前的顺序，两件事拼起来才是一整套流程。</p><p>「清单限制灵活性，高手靠盘感」这个反驳也先给公道话：盘感在高频反馈的场景里真能练出来——一天几十次出手、当天就知道对错，反馈密到足以校准直觉。它失效的边界在频率：一年只决策几次的长期投资，反馈慢到几乎不校准，等一套「盘感」被验证可靠，往往已经过了几轮牛熊。清单不取消判断——每一步仍要你亲口给判定；它禁的只有两件事：跳步，漏项。<strong>清单不取消判断，它给判断排顺序。</strong></p><p>载体是格式本身：每一步＝一个问题＋通过标准＋不通过出口。出口是清单与「心得体会」的分界线——判定不过时做什么，事先写死：放弃、等待、换工具，不恋战。</p><h3 id="七步清单" tabindex="-1">七步清单 <a class="header-anchor" href="#七步清单" aria-label="Permalink to &quot;七步清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步</th><th>问什么</th><th>通过标准</th><th>不通过出口</th></tr></thead><tbody><tr><td>① 生意</td><td>钱从哪来？</td><td>一句话说清，且自己信（商业模式，本章）</td><td>说不清＝圈外 → 放弃（能力圈，第 8 章）</td></tr><tr><td>② 护城河</td><td>优势是什么，十年后还在吗？</td><td>点得出优势类型，答得出十年之问（第 8 章）</td><td>答不出 → 不投，降级观察</td></tr><tr><td>③ 财报体检</td><td>利润是真的吗？</td><td>五项指标无红旗（第 6 章）</td><td>任一红旗 → 放弃或降级观察</td></tr><tr><td>④ 估值</td><td>现在贵不贵？</td><td>盈利收益率过存款锚粗筛，价格在七折线下（第 7、8 章）</td><td>贵 → 等待（继续观察）；数据变脸 → 放弃</td></tr><tr><td>⑤ 趋势与位置</td><td>当下什么状态？</td><td>一句描述说得清，不带预测（第 5 章）</td><td>描述不出 → 不参与看不懂的阶段</td></tr><tr><td>⑥ 风险与仓位</td><td>输得起多少？</td><td>三个数（可亏额、止损价、数量）算得出（第 9、11 章）</td><td>算不出或买不起一手 → 不硬买</td></tr><tr><td>⑦ 决策</td><td>买、不买、还是观察？</td><td>三选一＋理由＋推翻条件，落纸留痕（第 12 章）</td><td>写不出理由 → 默认「不买」</td></tr></tbody></table><p>次序有讲究：先问公司（①②③），再问价格（④⑤），最后问自己（⑥⑦）。②③同属「公司问」，先后可以互换——估算的原料必须是真盈利（体检先行，第 8 章），本章取先问优势再验成色；两处口径一致：公司问完才轮到价格。把次序倒过来的人——先看价格涨没涨，再回头找理由——就是开篇那个从分时图开始研究的人。</p><h3 id="组装式-十三块积木串成一条流程" tabindex="-1">组装式：十三块积木串成一条流程 <a class="header-anchor" href="#组装式-十三块积木串成一条流程" aria-label="Permalink to &quot;组装式：十三块积木串成一条流程&quot;">​</a></h3><p><strong>研究清单＝商业模式（本章）＋护城河十年之问（第 8 章）＋财报体检（第 6 章）＋估值与安全边际（第 7、8 章）＋趋势描述（第 5 章）＋回撤与预算反推（第 9、11 章）＋留痕防御（第 12 章）⇒ 一条带出口的进场流程。</strong></p><p>组装证据看两点就够：其一，这张表里没有一个新公式，每一步的判定都由已建立的接口就地完成，免登录的公开披露就是全部原料；其二，它与四道闸（第 8 章）首尾相接——①并入了能力圈三问，②③④就是闸门的展开，新增的⑤⑥⑦把「该不该买」接上「买多少」与「买了怎么改判」。本章真正的新东西只有两个名字与三件新事：排序、出口、台账。</p><h2 id="演练-一份七步走查台账-教学演示" tabindex="-1">演练：一份七步走查台账（教学演示） <a class="header-anchor" href="#演练-一份七步走查台账-教学演示" aria-label="Permalink to &quot;演练：一份七步走查台账（教学演示）&quot;">​</a></h2><p>口径先立好：下面这份记录只示范格式与判定方法。全部材料来自免登录公开信息（行情软件资料页与交易所披露）；只主张长期公开特征并标「约」——指近十年公开年报反复呈现的稳定形态，不替代你抄的当下数字；一切随行情变动的数字留白成空格。示例公司是贵州茅台（600519）——选它只因为公开度最高，历史快照有档可查（第 8 章），不构成任何推荐；换成任何一家公司，台账格式一字不改。</p><p>① 生意——钱从哪来？记录：把酿好的白酒通过经销商与直营渠道卖出去，按瓶收现钱；公开财报长年挂着一笔可观的预收款项（现行科目名「合同负债」）——经销商先打款、后拿货（长期公开特征，约）。能力圈三问顺带过一遍：谁在抢（高端白酒短名单上的另外几家）、亏了能不能说清（限价、消费场景变化这类公开原因），都答得出（第 8 章）。判定：通过（演示）。出口在旁：换一家公司若一句话说不清，出口当场生效——放弃，不恋战。</p><p>② 护城河——优势是什么，十年后还在吗？记录：优势点得出类型——品牌（宴请桌上「拿得出手」的位置）与产地工艺的独特性（公开资料的地理标志产区口径）；十年之问按长期特征给演示答案：十年后这个牌子还在，常识级别就敢判「是」。判定：通过（演示）。这一步的输出喂给第④步：「还能赚多少年」填进估值区间的年数（第 8 章）。</p><p>③ 财报体检——利润是真的吗？五项体检（第 6 章口径）全部能在资料页与年报里查到：毛利率长期站在 90% 以上（约，长期公开特征）；净利率长期在四成以上（约）；利润含金量（现金流量表的经营现金流 ÷ 利润表的净利润）长期口径充足，最新一年的数由你抄表复核；应收账款长期小到近乎可以忽略（约）——先收钱模式的直接后果，应收-营收增速差的红旗形态天然缺席；货币资金厚、有息负债几乎缺席（约），「存贷双高」（存款高、借款也高的可疑形状）不存在。判定：通过（演示）。备注沿用体检思路、阈值为本章口径：体检管筛查不管判决，连续两年的恶化才算趋势（本章取两年为升级阈值），单年波动不定罪。</p><p>④ 估值——现在贵不贵？记录（演示留白）：这一步的判定依赖你打开软件那一刻的报价，台账留空格——当下市盈率＝<strong><strong>，股息率＝</strong></strong>，盈利收益率＝1 ÷ 市盈率＝____。存款锚是无风险利率的课程近似（约 0.95%，第 7 章口径，以银行最新挂牌为准），盈利收益率对照它判「高于 / 低于」；再估内在价值区间与七折线（第 8 章），看市值落在七折线上还是下；重资产行业可辅以市净率（第 7 章）。判定：演示不代填——空格本身就是台账。出口有两种：公司过、价格不过 → 等待（继续观察）；财报形态变脸 → 出口升级为放弃。等的时候钱不闲着，机会成本按存款锚计（货币时间价值，第 1 章）。</p><p>⑤ 趋势与位置——当下什么状态？记录（演示留白）：打开K线（第 4 章），按「高点低点是否抬升」三选一（上升 / 下降 / 震荡，第 5 章），加一句价格站在 20 日、60 日均线上方还是下方。只用描述，不用预测；阳线与阴线、上影线与下影线、成交量不必逐根解读，金叉与死叉在这里只是状态词——把交叉当买入按钮的那笔账，回测尺随时可以再量一次（第 5 章）。判定：演示不代填。这一步不否决好公司，它只回答「现在处于哪一段」；描述不出的出口是不参与看不懂的阶段。</p><p>⑥ 风险与仓位——输得起多少？三个数上台账：单笔可亏额＝总资金 × 单笔风险预算（1%–2%，第 11 章）；止损价——来自价值失效位或技术位（支撑与压力，第 5 章），不来自成本价；可买数量＝可亏额 ÷（买价 − 止损价），按手取整（一手 100 股）。演示一笔（示意数字，非任何建议价位）：总资金 10 万、预算 1%，可亏 1000 元；买价粗取 1000 元、止损 850 元，每股风险 150 元，1000 ÷ 150 ≈ 6.7 股——连一手都买不起（这家公司的股价长期在千元量级，约）。第⑥步此刻做了件诚实的事：它宣布这只票与你的预算不匹配，出口＝不硬买——放大止损去凑手数，一手的风险就是 150 × 100 = 15,000 元，等于把预算偷偷改成 15%；合法的去向是换工具（宽基指数基金或 ETF 起步，第 13 章）或继续攒预算。顺带量历史最惨：波动率量日常颠簸，真正要预算的是最深那段——历史最大回撤接近腰斩（约，月线图上一量便知，第 9 章），盈亏不对称与回本涨幅一并写进备注（第 9 章）。执行层的旧规矩照旧：挂单在集合竞价还是连续竞价、T+1 的可卖日、佣金与过户费、印花税三笔过路钱（第 3 章）；跌停封板时止损指令也可能排队（涨跌停板，第 3 章）——指令不是保险箱，预算才是第一道闸。</p><p>⑦ 决策——买、不买、还是继续观察？演示输出：继续观察。理由（台账原话）：①②③按长期公开特征通过演示；④⑤⑥的判定依赖当下报价与你自己的预算，记录停在空格上。推翻条件（改判只认这两条）：其一，第③步复查出现任一红旗——含金量连续两年低于 100%、应收增速远超营收、存贷双高——改判「不买」；其二，价格落进你的七折线（第 8 章），且第⑥步预算装得下至少一手——改判「买」。留痕的意义在持有期兑现：处置效应会拿成本价坐上决策席（第 12 章），台账上的推翻条件是唯一合法的改判依据——判定材料与成本价无关。写不出理由的那一栏，默认答案就是「不买」。</p><h2 id="验证-轮到你走一遍" tabindex="-1">验证：轮到你走一遍 <a class="header-anchor" href="#验证-轮到你走一遍" aria-label="Permalink to &quot;验证：轮到你走一遍&quot;">​</a></h2><p>环境先声明：一部手机或一台电脑即可，全部任务免登录、免开户。行情与资料用任一免费行情软件（电脑端的 F10 靠键盘调出，手机端用「资料」标签）；年报与公告在巨潮资讯网与沪深交易所官网免登录可查。示例沿用 600519——它只是练习靶子，换任何一家你好奇的公司，清单一视同仁。</p><ul><li>[ ] 第②步留痕：打开 F10 或公司官网「核心竞争力」一栏，写下优势类型（品牌/成本/网络效应/牌照/转换成本五选一）与十年之问的答案各一句；应得到两句可留痕的判定，与台账第②步同型对照。</li><li>[ ] 找到 F10（先猜后做）：先猜 F10 弹出的第一屏是行情走势还是公司资料。电脑端输入 600519 回车后按 F10 键，手机端在报价页下方找「资料 / F10 / 简况」入口；应看到一栏栏资料标签（公司概况、股东研究、财务分析）——分时图留在行情页，研究从这里开始。</li><li>[ ] 第①步填空：在公司概况里找到主营业务一栏，抄成一句话——钱从哪来；应得到一句能念给外行听的话，与走查台账第①步逐句对照。念不顺时出口生效：这家公司在你的圈外。</li><li>[ ] 第③步毛利率（先猜后做）：先三选一写下猜测——最近一年的毛利率在 70%–80%、80%–90%、还是 90% 以上。在财务分析里找到毛利率；应看到最近多年停在 90% 以上（以当日软件显示为准，与「长期公开特征」口径对上；猜低了说明印象与披露之间有距离）。</li><li>[ ] 利润含金量（先猜后做）：先二选一——最近一年经营现金流 ÷ 净利润，大于 1 还是小于 1？抄两个数相除；应得到一个比值与判定（单年波动不定罪，连续两年偏低才升级红旗——本章口径）。</li><li>[ ] 应收红旗检查：先猜应收账款相对营收的量级。抄最近一年营收与应收账款，算应收 ÷ 营收；应得到一个接近零的量级（约百分之几以内），且看不到「应收增速远超营收」的形态。</li><li>[ ] 货币资金对照：在资产负债表里抄货币资金与短期借款、长期借款；应看到现金远厚于借款（长期公开特征口径），「存贷双高」的形状缺席（第 6 章）。</li><li>[ ] 第④步估值记录：抄下当下市盈率与股息率，算盈利收益率＝1 ÷ PE，与存款锚（约 0.95%，第 7 章口径，以银行最新挂牌为准）比较；应得到「高于 / 低于」一个明确判定——两个答案都合法，判定句落进台账。</li><li>[ ] 第⑤步一句描述：切到K线，调出 20 日与 60 日均线；按「高点低点是否抬升」写三选一（上升 / 下降 / 震荡），加一句价格在均线上方还是下方；应得到一句不含「会涨」「要跌」等预测词的状态描述——写得出来，第⑤步通过。</li><li>[ ] 第⑥步反推：写下你的总资金 × 1%，得单笔可亏额；设一个止损价（来自价值失效位或技术位）；应得到可买数量＝可亏额 ÷（买价 − 止损价）的一个数——不足一手（100 股）时，出口写明「预算不匹配，不硬买」。</li><li>[ ] 第⑦步留痕：按买 / 不买 / 继续观察三选一写一行台账，附一句理由与一条推翻条件；应得到不超过三行的书面留痕，格式与走查台账第⑦步一致。</li><li>[ ] 变体判据：把第①步用到另一家业务横跨几个不相干行业的公司上；应看到「一句话说得清」与「说不清」两种结果可以明确区分——说不清不等于公司差，只等于你圈外，出口照常生效。判据能区分通过与不通过，清单才算装好。</li></ul><p>排错分支：找不到 F10——电脑端按键要在个股页面生效，手机端入口叫「资料」「简况」或「F10」；指标名对不上——不同软件叫「销售毛利率」「归母净利润」等名目，认准利润表口径的算法（第 6 章）即可，名目不改算术；想看原始年报——巨潮资讯网搜 600519，进「公告」筛「年度报告」，PDF 里搜「毛利率」「经营活动产生的现金流量净额」直接定位；数字与正文对不上——软件显示最新披露值，正文只主张长期形态，判据读形态不抠单年。</p><p>清单每一条的判定材料都由你亲手抄、亲手算：数字是你的，判定是你的，出口也是你走的。这份验证不向你保证结果，只向你保证过程可检查——这正是研究清单与「听消息」的分界线。</p><h2 id="收束-几千页资料-压成七问" tabindex="-1">收束：几千页资料，压成七问 <a class="header-anchor" href="#收束-几千页资料-压成七问" aria-label="Permalink to &quot;收束：几千页资料，压成七问&quot;">​</a></h2><p>开篇那个行情页现在可以重新打开了：F10 的几千页一页没少，分时图也还在首页——变的是读取顺序。清单把它们排成七个可判定的问题：钱从哪来（①商业模式）、优势能撑几年（②）、利润是真的吗（③）、现在贵不贵（④）、当下什么状态（⑤）、输得起多少（⑥）、买不买（⑦）。分时图没有被开除，它只是被排到了第⑤步，一句描述完就退场。<strong>研究输在顺序，不输在勤奋——清单管的正是顺序。</strong></p><p>本章新增两个名字：商业模式——一句话说清钱从哪来，说不清就是圈外；研究清单——每步带通过标准与不通过出口的检查序列。外加一条台账习惯：改判只认推翻条件，不认成本价。</p><p>走歪高发区有两处。其一，把清单当赚钱算式——七步全过只说明「可以买」，不承诺「买了就涨」，第④步的等待可能很长；它保证的是不买错，不是必买到。其二，台账不留痕——三个月后行情与成本价会联手改写你的记忆，纸面上的推翻条件是处置效应唯一认账的判官（第 12 章）。</p><p>清单也有够不着的部分：行业专业知识（政策、技术路线）不在七步之内，走到圈边就认怂；股票整体该配多少，由资产配置与再平衡管（第 10 章），按清单连选五只同行业票也不叫分散化（相关性，第 10 章）；不想逐家研究的人，宽基指数基金定投是合法的默认答案（第 13 章），挑的时候费率照旧压低。买进来之后的长期账各归各章：收益由盈利与复利接力（第 1 章），名义回本要过通货膨胀的折旧（第 1 章），最后以实际购买力验收。延伸去向：把七步清单与预算规则写成一页纸计划（第 15 章）；更远的进阶地图（第 16 章）。</p><p>本章走查与任务全部基于免登录公开信息（行情软件资料页、巨潮资讯网与交易所披露）；示例公司仅作教学演示，不构成任何投资建议、不荐股；存款锚等时效数字以最新公告为准。</p><h3 id="自查-五份用歪的清单-逐份纠偏" tabindex="-1">自查：五份用歪的清单，逐份纠偏 <a class="header-anchor" href="#自查-五份用歪的清单-逐份纠偏" aria-label="Permalink to &quot;自查：五份用歪的清单，逐份纠偏&quot;">​</a></h3><ol><li>某公司净利润连年增长，但你算出利润含金量连续两年低于 100%，应收账款增速比营收增速高出 25 个百分点。清单哪一步亮了什么旗？出口是什么？</li><li>一家公司第①②③步全过，第④步卡住：价格远在七折线上方。这一步的出口写「放弃」还是「等待」？台账上该记什么？</li><li>朋友说：「我盘感好，不用搞清单。」写两句回应，每句用一条本章判据。</li><li>丙公司做订阅制：客户先付一年服务费、服务按月履约。它的收入确认与现金到账各在哪一端？和「先发货后收钱」的赊销公司相比，两家在资产负债表上方向相反的科目各是什么？下游集体拖款（或客户不再续订）时谁先倒，为什么？</li><li>你的台账写着「继续观察，改判条件：价格落进七折线」。三个月后群里人人晒这只票，你手痒想追。动用哪条警报、哪份材料？</li></ol><details><summary>自查答案</summary><ol><li>第③步两面红旗：利润含金量连续两年低于 100%，应收-营收增速差激增（超过 20 个百分点即为激增口径，第 6 章）。出口＝放弃，或降级为观察名单继续盯下一期披露。判据与「净利润在涨」无关——体检盯的是利润的成色，不是增速。</li><li>等待（继续观察），不是放弃。放弃留给①②的圈外与③的红旗；公司过、价格不过是「好公司与好股票」隔着的那层（第 8 章）。台账记估值空格（市盈率、股息率、盈利收益率、七折线）与改判条件——价格落进七折线且第⑥步预算装得下，才改判「买」。</li><li>判据一：一年决策几次的频率下，反馈慢到校准不了盘感——它没有被验证的机会。判据二：清单不取消判断，只禁跳步与漏项；真有盘感，把每次判定写成台账照样赢——写不出台账，恰好说明判定还没成形。</li><li>甲的反向科目是预收款项（它欠客户货），乙是应收账款（客户欠它钱）。乙先倒：乙的利润停在纸面债权上，资金被下游占用；拖款一来，垫资立刻变成现实的缺口，而甲手里多的是客户预付的定金。</li><li>动用拥挤警报（身边人晒单成风在词表上，第 12 章）：只登记、不新增买入。材料是你的台账：改判「买」只认推翻条件——价格落进七折线且预算装得下，群消息不在合法依据里；手痒本身正是处置效应与从众（第 12 章）想在进场前就接管决策的信号。</li></ol></details>',48)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
